import { z } from 'zod'
import { shipmentSchema, type Shipment } from './shipment.js'

const documentSchema = z.object({
  name: z.string().min(1),
  text: z.string().max(100_000).optional(),
  images: z.array(z.string().startsWith('data:image/')).max(20).optional(),
}).refine((document) => document.text || document.images?.length, {
  message: 'A document needs extracted text or at least one image.',
})

export const extractionRequestSchema = z.object({
  documents: z.array(documentSchema).min(1).max(10),
})

export type ExtractionRequest = z.infer<typeof extractionRequestSchema>

type ChatResponse = {
  choices?: Array<{ message?: { content?: string } }>
}

const extractionInstructions = `You extract US customs-entry shipment data from shipping documents.
Return only JSON that matches the provided schema. Never invent a value: use {"value":null,"confidence":0} when documents do not provide it. Confidence must be 0 to 1. Preserve document values even when they conflict; add concise conflicts using field paths and the competing values. Do not generate XML. Extract only facts visible in the documents.`

function parseModelJson(content: string): unknown {
  const json = content.trim().replace(/^```json\s*|\s*```$/g, '')
  return JSON.parse(json)
}

export async function extractShipment(
  request: ExtractionRequest,
  apiKey: string,
  model = 'openrouter/free',
  fetcher: typeof fetch = fetch,
): Promise<Shipment> {
  const content = request.documents.flatMap((document) => [
    { type: 'text', text: `Document: ${document.name}\n${document.text ?? ''}` },
    ...(document.images ?? []).map((image) => ({ type: 'image_url', image_url: { url: image } })),
  ])

  const response = await fetcher('https://openrouter.ai/api/v1/chat/completions', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      model,
      temperature: 0,
      messages: [
        { role: 'system', content: extractionInstructions },
        {
          role: 'user',
          content: [
            { type: 'text', text: `Shipment JSON schema:\n${JSON.stringify(z.toJSONSchema(shipmentSchema))}` },
            ...content,
          ],
        },
      ],
    }),
  })

  if (!response.ok) {
    throw new Error(`OpenRouter extraction failed (${response.status}).`)
  }

  const data = await response.json() as ChatResponse
  const contentText = data.choices?.[0]?.message?.content
  if (!contentText) {
    throw new Error('OpenRouter returned no extraction result.')
  }

  return shipmentSchema.parse(parseModelJson(contentText))
}

