}

function escapeXml(value: string | number): string {
  return String(value).replace(/[<>&'\"]/g, (character) => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', "'": '&apos;', '"': '&quot;' })[character]!)
}

function element(name: string, value: string | number | null | undefined): string {
  return value == null || value === '' ? '' : `<${name}>${escapeXml(value)}</${name}>`
}

export function renderNetchbXml(shipment: Shipment): RenderResult {
  const errors = missingRequiredFields(shipment)
  const lineErrors = shipment.lines.flatMap((line, index) => ['countryOfOrigin', 'htsCode', 'value'].flatMap((field) => line[field as 'countryOfOrigin' | 'htsCode' | 'value'].value == null ? [`lines.${index}.${field}`] : []))
  if (errors.length || lineErrors.length) return { errors: [...errors, ...lineErrors] }

  const lines = shipment.lines.map((line) => `
        <line-item>
          ${element('country-origin', line.countryOfOrigin.value)}
          <tariffs><tariff>${element('tariff-no', line.htsCode.value?.replace(/\D/g, ''))}${element('value', line.value.value)}</tariff></tariffs>
        </line-item>`).join('')
  const totalValue = shipment.lines.reduce((total, line) => total + Number(line.value.value ?? 0), 0)

  return {
    xml: `<?xml version="1.0" encoding="UTF-8"?>
<entry xmlns="http://www.netchb.com/xml/entry" xmlns:data="http://www.netchb.com/xml/data">
  <entry-no><system-generated /></entry-no>
  <header>
    ${element('importer-tax-id', shipment.importer.taxId?.value)}
    ${element('importer-name', shipment.importer.name.value)}
    ${element('processing-port', shipment.transport.processingPort.value)}
    ${element('entry-port', shipment.transport.entryPort.value)}
    ${element('entry-date', shipment.entry.date.value)}
    ${element('entry-type', shipment.entry.type.value)}
    ${element('bond-type', shipment.entry.bondType.value)}
    ${element('gross-weight', shipment.totals.grossWeight.value)}
    ${element('total-entry-value', Math.round(totalValue))}
    ${element('vessel-name', shipment.transport.vessel.value)}
    ${element('unlading-port', shipment.transport.entryPort.value)}
    ${element('arrival-date', shipment.transport.arrivalDate.value)}
  </header>
  <manifest />
  <invoices>
    <invoice>
      ${element('invoice-no', shipment.invoice.number.value)}
      <line-items>${lines}
      </line-items>
    </invoice>
  </invoices>
</entry>`,
  }
}

