.drop-zone { display: block; cursor: pointer; border: 2px dashed var(--accent-border); border-radius: .5rem; margin: 1rem 0; padding: 1.25rem; text-align: center; }
.drop-zone input { display: block; margin: .75rem auto 0; max-width: 100%; }
.files { padding-left: 1.25rem; }
.files span, small { color: var(--text); font-size: .8rem; }
button { background: var(--accent); border: 0; border-radius: .4rem; color: white; cursor: pointer; font: inherit; padding: .65rem 1rem; }
button:disabled { cursor: not-allowed; opacity: .5; }
button.secondary { background: transparent; border: 1px solid var(--border); color: var(--text-h); }
.section-heading { align-items: center; display: flex; justify-content: space-between; gap: 1rem; }
.notice { border-radius: .4rem; margin: 1rem 0; padding: .75rem 1rem; }
.notice ul { margin: .5rem 0 0; }
.notice.warning { background: #fff5d8; color: #5f4200; }
.notice.error { background: #ffe5e5; color: #7b1717; }
.notice.success { background: #e5f8e8; color: #176229; }
.form-grid { display: grid; gap: 1rem; grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr)); }
fieldset { border: 1px solid var(--border); border-radius: .4rem; margin: 1rem 0; padding: 1rem; }
legend { color: var(--text-h); font-weight: 600; padding: 0 .25rem; }
.field { display: block; margin-bottom: .75rem; }
.field span { color: var(--text-h); display: block; font-size: .9rem; margin-bottom: .25rem; }
.field input { border: 1px solid var(--border); border-radius: .3rem; box-sizing: border-box; font: inherit; padding: .45rem; width: 100%; }
.field.missing input { border-color: #d08d00; }
.field.low-confidence input { border-color: #bb7100; }
.lines .field { margin: 0; }
.xml-result { margin-top: 1.5rem; }
.xml-result pre { background: #17202a; border-radius: .4rem; color: #f7f9fb; max-height: 28rem; overflow: auto; padding: 1rem; white-space: pre-wrap; }

