--- D:\Agentic-AI\sefer-ha\src\lib\netchb-renderer.ts
+++ D:\Agentic-AI\sefer-ha\src\lib\netchb-renderer.ts
@@ -0,0 +1,83 @@
+import { requiredShipmentFields, type Shipment } from './shipment.js'
+
+export type RenderResult = { xml: string } | { errors: string[] }
+
+function valueOf(value: unknown): string | number | null {
+  return typeof value === 'object' && value !== null && 'value' in value ? (value as { value: string | number | null }).value : null
+}
+
+function missingRequiredFields(shipment: Shipment): string[] {
+  const required = requiredShipmentFields.filter((path) => valueOf(path.split('.').reduce<unknown>((current, key) => (current as Record<string, unknown>)?.[key], shipment)) == null)
+  const lineErrors = shipment.lines.flatMap((line, index) => ['countryOfOrigin', 'htsCode', 'value'].flatMap((key) => valueOf(line[key as 'countryOfOrigin' | 'htsCode' | 'value']) == null ? [`lines.${index}.${key}`] : []))
+  return [...required, ...lineErrors]
+}
+
+function escapeXml(value: string | number): string {
+  return String(value).replace(/[<>&'"]/g, (character) => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', "'": '&apos;', '"': '&quot;' })[character]!)
+}
+
+function element(name: string, value: string | number | null | undefined): string {
+  return value == null || value === '' ? '' : `<${name}>${escapeXml(value)}</${name}>`
+}
+
+function money(value: number | null): string | null {
+  return value == null ? null : value.toFixed(2)
+}
+
+function port(value: string | null): string | null {
+  return value && /^\d{4}$/.test(value) ? value : null
+}
+
+function foreignPort(value: string | null): string | null {
+  return value && /^\d{5}$/.test(value) ? value : null
+}
+
+export function renderNetchbXml(shipment: Shipment): RenderResult {
+  const errors = missingRequiredFields(shipment)
+  if (errors.length) return { errors }
+
+  const totalValue = shipment.lines.reduce((total, line) => total + Number(line.value.value ?? 0), 0)
+  const manifest = shipment.transport.billOfLading.value && shipment.totals.packages.value != null
+    ? `<bill-of-lading>${element('house-bill', shipment.transport.billOfLading.value)}${element('quantity', Math.round(shipment.totals.packages.value))}${element('unit', 'PKG')}</bill-of-lading>`
+    : ''
+  const containers = shipment.transport.containers.map((container) => element('container-number', container.value)).join('')
+  const lines = shipment.lines.map((line) => {
+    const quantity = line.quantity.value != null && line.unit.value ? `${element('quantity1', line.quantity.value)}${element('unit-of-measure1', line.unit.value)}` : ''
+    return `<line-item>${element('country-origin', line.countryOfOrigin.value)}<tariffs><tariff>${element('tariff-no', line.htsCode.value?.replace(/\D/g, ''))}${element('value', money(line.value.value))}${quantity}</tariff></tariffs>${element('lading-port', foreignPort(shipment.transport.loadingPort.value))}${element('gross-weight', shipment.totals.grossWeight.value == null ? null : Math.round(shipment.totals.grossWeight.value))}</line-item>`
+  }).join('')
+  const currency = shipment.invoice.currency.value?.toUpperCase()
+  const dischargePort = port(shipment.transport.dischargePort.value) ?? port(shipment.transport.entryPort.value)
+
+  return {
+    xml: `<?xml version="1.0" encoding="UTF-8"?>
+<entry xmlns="http://www.netchb.com/xml/entry" xmlns:data="http://www.netchb.com/xml/data">
+  <entry-no><system-generated /></entry-no>
+  <header>
+    ${element('importer-tax-id', shipment.importer.taxId.value)}
+    ${element('importer-name', shipment.importer.name.value)}
+    <ultimate-consignee>${element('consignee-name', shipment.consignee.name.value)}</ultimate-consignee>
+    ${element('processing-port', shipment.transport.processingPort.value)}
+    ${element('entry-port', shipment.transport.entryPort.value)}
+    ${element('entry-date', shipment.entry.date.value)}
+    ${element('entry-type', shipment.entry.type.value)}
+    ${element('bond-type', shipment.entry.bondType.value)}
+    ${element('gross-weight', shipment.totals.grossWeight.value == null ? null : Math.round(shipment.totals.grossWeight.value))}
+    ${element('total-entry-value', Math.round(totalValue))}
+    ${element('description', shipment.lines[0]?.description.value)}
+    ${element('vessel-name', shipment.transport.vessel.value)}
+    ${element('unlading-port', dischargePort)}
+    ${element('arrival-date', shipment.transport.arrivalDate.value)}
+    ${element('voyage-no', shipment.transport.voyage.value)}
+  </header>
+  <manifest>${manifest}</manifest>
+  ${containers ? `<containers>${containers}</containers>` : ''}
+  <invoices>
+    <invoice>
+      ${element('invoice-no', shipment.invoice.number.value?.replace(/[^A-Za-z\d-]/g, ''))}
+      ${currency && currency !== 'USD' ? `<foreign-currency>${element('currency-code', currency)}</foreign-currency>` : ''}
+      <line-items>${lines}</line-items>
+    </invoice>
+  </invoices>
+</entry>`,
+  }
+}

