const countryCodes: Record<string, string> = {
  vietnam: 'VN',
  bangladesh: 'BD',
  china: 'CN',
  'hong kong': 'HK',
  taiwan: 'TW',
  india: 'IN',
  thailand: 'TH',
  indonesia: 'ID',
  malaysia: 'MY',
  cambodia: 'KH',
  'south korea': 'KR',
  korea: 'KR',
  japan: 'JP',
  mexico: 'MX',
  canada: 'CA',
  germany: 'DE',
  'united kingdom': 'GB',
  uk: 'GB',
  italy: 'IT',
  france: 'FR',
  spain: 'ES',
  turkey: 'TR',
  pakistan: 'PK',
  'sri lanka': 'LK',
  philippines: 'PH',
  singapore: 'SG',
  'united arab emirates': 'AE',
  brazil: 'BR',
}

// Bond types: XSD enumeration is 00, 08, 09. Labels map to the documented
// code; 09 is the single-transaction value and is used in fixtures only as a
// clearly marked demo value, never invented for a real shipment.
const bondTypes: Record<string, string> = {
  '00': '00',
  '08': '08',
  '09': '09',
  'no bond': '00',
  unsecured: '00',
  continuous: '08',
  'continuous bond': '08',
  single: '09',
  'single transaction': '09',
  'single entry': '09',
}

export function resolvePortCode(value: string | null): string | null {
  if (!value) return null
  const trimmed = value.trim()
  if (/^\d{4}$/.test(trimmed)) return trimmed
  return usPortCodes[trimmed.toLowerCase()] ?? null
}

export function resolveForeignPortCode(value: string | null): string | null {
  if (!value) return null
  const trimmed = value.trim()
  return /^\d{5}$/.test(trimmed) ? trimmed : null
}

export function resolveCountryCode(value: string | null): string | null {
  if (!value) return null
  const trimmed = value.trim()
  if (/^[A-Za-z]{2}$/.test(trimmed)) return trimmed.toUpperCase()
  return countryCodes[trimmed.toLowerCase()] ?? null
}

export function resolveBondType(value: string | null): string | null {
  if (!value) return null
  const trimmed = value.trim()
  return bondTypes[trimmed.toLowerCase()] ?? null
}

