import type { Conflict, Observation } from './shipment.js'
import { normalizeFieldValue } from './normalize.js'

// Deterministic, document-agnostic conflict detection.
//
// Every observation is a value the extractor saw for a field in a specific
// document. Values for the same field are normalized (OCR-aware) and grouped;
// a field is in conflict when two or more distinct normalized values appear.
// This works for any field and any combination of documents.

export function detectConflicts(observations: Observation[]): Conflict[] {
  const groups = new Map<string, Map<string, string>>()

  for (const observation of observations) {
    const normalized = normalizeFieldValue(observation.field, observation.value)
    if (!normalized) continue
    const byValue = groups.get(observation.field) ?? new Map<string, string>()
    groups.set(observation.field, byValue)
    if (!byValue.has(normalized)) byValue.set(normalized, observation.value.trim())
  }

  const conflicts: Conflict[] = []
  for (const [field, byValue] of groups) {
    if (byValue.size < 2) continue
    conflicts.push({ field, values: [...byValue.values()] })
  }
  return conflicts
}

// Re-normalize conflicts that came from the model: drop disagreements that are
// only OCR/formatting noise, and merge duplicates of the same field.
export function normalizeConflicts(conflicts: Conflict[]): Conflict[] {
  const merged = new Map<string, Map<string, string>>()

  for (const conflict of conflicts) {
    const byValue = merged.get(conflict.field) ?? new Map<string, string>()
    merged.set(conflict.field, byValue)
    for (const value of conflict.values) {
      const normalized = normalizeFieldValue(conflict.field, value)
      if (normalized && !byValue.has(normalized)) byValue.set(normalized, value.trim())
    }
  }

  const result: Conflict[] = []
  for (const [field, byValue] of merged) {
    if (byValue.size < 2) continue
    result.push({ field, values: [...byValue.values()] })
  }
  return result
}

export function mergeConflicts(...lists: Conflict[][]): Conflict[] {
  return normalizeConflicts(lists.flat())
}

// Single entry point used by the API and the UI so both agree on conflicts.
export function reconcileConflicts(shipment: { conflicts: Conflict[]; observations: Observation[] }): Conflict[] {
  return mergeConflicts(normalizeConflicts(shipment.conflicts), detectConflicts(shipment.observations))
}

import { getExtractedValue, requiredShipmentFields, type Shipment } from './shipment.js'
import { isValidBondType, isValidUsPortCode, resolveCountryCode, resolveForeignPortCode, resolvePortCode } from './netchb-codes.js'

export type ValidationSeverity = 'error' | 'warning'

export type ValidationIssue = {
  path: string
  message: string
  severity: ValidationSeverity
}

// Generic validation for any shipment/document combination. Required values must
// be present; NetCHB codes must resolve to the exact XSD value. Unknown codes are
// surfaced here for manual review and are never inferred.
export function validateShipment(shipment: Shipment): ValidationIssue[] {
  const issues: ValidationIssue[] = []
  const add = (path: string, message: string, severity: ValidationSeverity = 'error') => issues.push({ path, message, severity })

  for (const path of requiredShipmentFields) {
    if (getExtractedValue(shipment, path) == null) add(path, 'Required value is missing.')
  }

  const usPorts: Array<[string, string | null, ValidationSeverity]> = [
    ['transport.processingPort', shipment.transport.processingPort.value, 'error'],
    ['transport.entryPort', shipment.transport.entryPort.value, 'error'],
    ['transport.dischargePort', shipment.transport.dischargePort.value, 'warning'],
  ]
  for (const [path, value, severity] of usPorts) {
    if (value != null && !resolvePortCode(value)) add(path, 'Not a recognized 4-digit CBP port code or known port name; select a valid code.', severity)
  }
  if (shipment.transport.loadingPort.value != null && !resolveForeignPortCode(shipment.transport.loadingPort.value)) {
    add('transport.loadingPort', 'Foreign port of loading must be a 5-digit code; it will be omitted from the XML.', 'warning')
  }

  const bondType = shipment.entry.bondType.value
  if (bondType != null && !isValidBondType(bondType)) add('entry.bondType', 'Bond type must be one of 00, 08, or 09.')

  if (shipment.entry.type.value != null && !/^\d{2}$/.test(shipment.entry.type.value.trim())) {
    add('entry.type', 'Entry type must be a 2-digit code.', 'warning')
  }

  shipment.lines.forEach((line, index) => {
    if (line.countryOfOrigin.value == null) add(`lines.${index}.countryOfOrigin`, 'Country of origin is required.')
    else if (!resolveCountryCode(line.countryOfOrigin.value)) add(`lines.${index}.countryOfOrigin`, 'Unknown country; provide a valid ISO alpha-2 code.')

    if (line.htsCode.value == null) add(`lines.${index}.htsCode`, 'HTS code is required.')
    else if (!/^\d{5,10}$/.test(line.htsCode.value.replace(/\D/g, ''))) add(`lines.${index}.htsCode`, 'HTS code should contain 5 to 10 digits.', 'warning')

    if (line.value.value == null) add(`lines.${index}.value`, 'Line value is required.')
  })

  const seen = new Set<string>()
  return issues.filter((issue) => {
    const key = `${issue.path}|${issue.message}`
    if (seen.has(key)) return false
    seen.add(key)
    return true
  })
}

export function errorPaths(issues: ValidationIssue[]): string[] {
  return [...new Set(issues.filter((issue) => issue.severity === 'error').map((issue) => issue.path))]
}

