function input(path: string, label: string, type: InputType = 'text', issues: IssueMap = new Map()): string {
  const extracted = getValue(state.shipment!, path) as FieldValue
  const issue = issues.get(path)
  const status = issue?.severity === 'error' || extracted.value == null ? 'missing' : issue || extracted.confidence < 0.75 ? 'low-confidence' : ''
  const source = extracted.source ? ` · ${escapeHtml(extracted.source.document)}${extracted.source.page ? ` p.${extracted.source.page}` : ''}` : ''
  const note = issue ? issue.message : extracted.value == null ? 'Missing' : `${Math.round(extracted.confidence * 100)}% confidence`
  const control = path === 'entry.bondType'
    ? bondTypeControl(path, extracted.value)
    : `<input data-field="${path}" data-type="${type}" type="${type}" value="${escapeHtml(extracted.value)}">`
  return `<label class="field ${status}"><span>${label}</span>${control}<small>${escapeHtml(note)}${source}</small></label>`
}

function bondTypeControl(path: string, value: unknown): string {
  const options = ['', '00', '08', '09'].map((code) => `<option value="${code}" ${String(value ?? '') === code ? 'selected' : ''}>${code === '' ? 'Select…' : code}</option>`).join('')
  return `<select data-field="${path}" data-type="text">${options}</select>`
}

function lineMarkup(index: number, issues: IssueMap): string {
  return `<fieldset><div class="section-heading"><legend>Invoice line ${index + 1}</legend><button type="button" class="secondary" data-remove-line="${index}" ${state.shipment!.lines.length === 1 ? 'disabled' : ''}>Remove line</button></div><div class="form-grid lines">${input(`lines.${index}.description`, 'Description', 'text', issues)}${input(`lines.${index}.countryOfOrigin`, 'Country of origin', 'text', issues)}${input(`lines.${index}.htsCode`, 'HTS code', 'text', issues)}${input(`lines.${index}.quantity`, 'Quantity', 'number', issues)}${input(`lines.${index}.unit`, 'Unit', 'text', issues)}${input(`lines.${index}.value`, 'Value', 'number', issues)}${input(`lines.${index}.manufacturer.name`, 'Manufacturer name', 'text', issues)}${input(`lines.${index}.manufacturer.address`, 'Manufacturer address', 'text', issues)}${input(`lines.${index}.manufacturer.taxId`, 'Manufacturer tax ID', 'text', issues)}</div></fieldset>`
}

function reviewMarkup(shipment: Shipment): string {
  ensureReviewShipment(shipment)
  const issues = validateShipment(shipment)
  const issueMap: IssueMap = new Map(issues.map((issue) => [issue.path, issue]))
  const conflicts = shipment.conflicts.map((conflict) => `<li><strong>${escapeHtml(conflict.field)}</strong>: ${escapeHtml(conflict.values.join(' / '))}</li>`).join('')
  const groups = reviewGroups.map((group) => `<fieldset><legend>${group.legend}</legend><div class="form-grid">${group.fields.map(([path, label, type]) => input(path, label, type, issueMap)).join('')}</div></fieldset>`).join('')
  const containers = shipment.transport.containers.map((container) => container.value).filter(Boolean).join(', ')
  const issuesNotice = issues.length
    ? `<aside class="notice warning"><strong>Needs review (${issues.length})</strong><ul>${issues.map((issue) => `<li><code>${escapeHtml(issue.path)}</code>: ${escapeHtml(issue.message)}</li>`).join('')}</ul></aside>`
    : '<aside class="notice success">Required review fields are complete.</aside>'
  const result = state.xml && state.validationValid
    ? `<section class="xml-result"><div class="section-heading"><h2>Validated NetCHB XML</h2><div class="actions"><button type="button" id="copy-xml" class="secondary">Copy XML</button><button type="button" id="download-xml">Download XML</button></div></div><pre><code>${escapeHtml(state.xml)}</code></pre></section>`
    : ''
  return `<section class="review"><div class="section-heading"><div><p class="eyebrow">Review</p><h2>Confirm shipment data</h2></div><button type="button" id="reset-review" class="secondary">Reset</button></div>${issuesNotice}${conflicts ? `<aside class="notice warning"><strong>Conflicts across documents</strong><ul>${conflicts}</ul></aside>` : ''}${groups}<fieldset><legend>Containers</legend><label class="field"><span>Container numbers</span><input id="containers" value="${escapeHtml(containers)}" placeholder="Comma-separated"><small>One or more container numbers, if present on the bill of lading.</small></label></fieldset>${shipment.lines.map((_, index) => lineMarkup(index, issueMap)).join('')}<div class="actions"><button type="button" id="add-line" class="secondary">Add invoice line</button><button type="button" id="generate-xml">Generate NetCHB XML</button></div>${state.validationErrors.length ? `<aside class="notice error"><strong>XML validation errors</strong><ul>${state.validationErrors.map((error) => `<li>${escapeHtml(error)}</li>`).join('')}</ul></aside>` : ''}${result}</section>`
}

