// document. Values for the same field are normalized (OCR-aware) and grouped;
// a field is in conflict when two or more distinct normalized values appear.
// This works for any field and any combination of documents.

export function detectConflicts(observations: Observation[]): Conflict[] {
  const groups = new Map<string, Map<string, string>>()

  for (const observation of observations) {
    const normalized = normalizeFieldValue(observation.field, observation.value)
    if (!normalized) continue
    const byValue = groups.get(observation.field) ?? new Map<string, string>()
    groups.set(observation.field, byValue)
    if (!byValue.has(normalized)) byValue.set(normalized, observation.value.trim())
  }

  const conflicts: Conflict[] = []
  for (const [field, byValue] of groups) {
    if (byValue.size < 2) continue
    conflicts.push({ field, values: [...byValue.values()] })
  }
  return conflicts
}

// Re-normalize conflicts that came from the model: drop disagreements that are
// only OCR/formatting noise, and merge duplicates of the same field.
export function normalizeConflicts(conflicts: Conflict[]): Conflict[] {
  const merged = new Map<string, Map<string, string>>()

  for (const conflict of conflicts) {
    const byValue = merged.get(conflict.field) ?? new Map<string, string>()
    merged.set(conflict.field, byValue)
    for (const value of conflict.values) {
      const normalized = normalizeFieldValue(conflict.field, value)
      if (normalized && !byValue.has(normalized)) byValue.set(normalized, value.trim())
    }
  }

  const result: Conflict[] = []
  for (const [field, byValue] of merged) {
    if (byValue.size < 2) continue
    result.push({ field, values: [...byValue.values()] })
  }
  return result
}

export function mergeConflicts(...lists: Conflict[][]): Conflict[] {
  return normalizeConflicts(lists.flat())
}

// Single entry point used by the API and the UI so both agree on conflicts.
export function reconcileConflicts(shipment: { conflicts: Conflict[]; observations: Observation[] }): Conflict[] {
  return mergeConflicts(normalizeConflicts(shipment.conflicts), detectConflicts(shipment.observations))
}

