import { classifyPort } from './netchb-codes.js'
import type { Shipment } from './shipment.js'

// U.S. customs port fields (processing-port, entry-port, unlading-port) must be
// 4-digit CBP Schedule D codes. A model sometimes places the foreign port of
// loading (for example "Cat Lai, HCMC, VN") into one of these fields. Clear it,
// lower confidence, and raise a review flag so the user confirms the real U.S.
// port instead of emitting invalid XML.

const usPortFields = [
  { path: 'processingPort', label: 'Processing port' },
  { path: 'entryPort', label: 'Entry port' },
  { path: 'dischargePort', label: 'Port of discharge' },
] as const

function addFlag(shipment: Shipment, field: string, message: string): void {
  if (!shipment.flags.some((flag) => flag.field === field && flag.message === message)) shipment.flags.push({ field, message })
}

export function sanitizeTransportPorts(shipment: Shipment): void {
  for (const { path, label } of usPortFields) {
    const field = shipment.transport[path]
    const { role, code } = classifyPort(field.value)
    if (role === 'foreign') {
      addFlag(shipment, `transport.${path}`, `${label} must be a 4-digit U.S. CBP Schedule D port, but the document provided the foreign port "${field.value}" (Schedule K ${code}). Confirm the correct U.S. port.`)
      field.value = null
      field.confidence = 0
    }
  }
}

