function portCodeHint(path: string): string {
  if (!state.shipment) return ''
  const value = (getValue(state.shipment, path) as FieldValue | undefined)?.value
  if (path === 'transport.loadingPort') {
    if (value == null) return 'Foreign port of loading (5-digit CBP Schedule K). Optional.'
    const code = resolveForeignPortCode(String(value))
    return code ? `Schedule K ${code}` : 'No verified Schedule K code — enter a 5-digit code or clear this field.'
  }
  if (path === 'transport.processingPort' || path === 'transport.entryPort' || path === 'transport.dischargePort') {
    if (value != null) {
      const { role, code } = classifyPort(String(value))
      if (role === 'foreign') return `Foreign port (Schedule K ${code}) — must be a U.S. CBP Schedule D port.`
      if (role === 'us') return isVerifiedUsPortCode(code ?? '') ? `CBP Schedule D ${code}` : `CBP Schedule D ${code} (not in the local verified list — confirm).`
      return 'Not a recognized U.S. CBP port — enter a Schedule D name or 4-digit code.'
