import type { Shipment } from './shipment.js'

// Deterministic invoice arithmetic checks. These never modify extracted values
// and never decide which side of a mismatch is wrong - they only compute an
// expected value, compare it to the stated value, and surface the difference for
// human review. Generic: it depends only on the normalized shipment model.

export type ArithmeticKind = 'line-amount' | 'line-subtotal' | 'invoice-total' | 'missing-input'

export type ArithmeticIssue = {
  path: string
  kind: ArithmeticKind
  expected: number | null
  stated: number | null
  difference: number | null
  message: string
  evidence: string
}

type Line = Shipment['lines'][number]
type Sourced = { source?: { document: string; page?: number } } | undefined

// ISO 4217 currencies whose minor unit is 1 (no decimal places).
const zeroDecimalCurrencies = new Set(['BIF', 'CLP', 'DJF', 'GNF', 'ISK', 'JPY', 'KMF', 'KRW', 'PYG', 'RWF', 'UGX', 'VND', 'VUV', 'XAF', 'XOF', 'XPF'])

export function currencyDecimals(currency: string | null | undefined): number {
  const code = currency?.trim().toUpperCase()
  return code && zeroDecimalCurrencies.has(code) ? 0 : 2
}

export function roundTo(value: number, decimals: number): number {
  const factor = 10 ** decimals
  return Math.round((value + Number.EPSILON) * factor) / factor
}

function money(value: number, decimals: number): string {
  return value.toFixed(decimals)
}

function sourceLabel(...fields: Sourced[]): string {
  for (const field of fields) {
    if (field?.source) return `${field.source.document}${field.source.page ? ` p.${field.source.page}` : ''}`
  }
  return ''
}

// A free sample carries no charge: explicitly marked, a zero unit price, or no
// unit price with a zero amount.
export function isFreeOfCharge(line: Line): boolean {
  if (line.freeOfCharge?.value === true) return true
  const unitPrice = line.unitPrice?.value ?? null
  const value = line.value.value
  return unitPrice === 0 || (unitPrice == null && value === 0)
}

export function validateArithmetic(shipment: Shipment): ArithmeticIssue[] {
  const issues: ArithmeticIssue[] = []
  const decimals = currencyDecimals(shipment.invoice.currency.value)

  shipment.lines.forEach((line, index) => {
    if (isFreeOfCharge(line)) return
    const quantity = line.quantity.value
    const unitPrice = line.unitPrice?.value ?? null
    const stated = line.value.value
    const evidence = sourceLabel(line.value, line.unitPrice, line.quantity)

    if (quantity == null && unitPrice == null && stated == null) return

    if (quantity == null || unitPrice == null || stated == null) {
      const missing = [quantity == null && 'quantity', unitPrice == null && 'unit price', stated == null && 'line amount'].filter(Boolean).join(', ')
      issues.push({ path: `lines.${index}.value`, kind: 'missing-input', expected: null, stated, difference: null, message: `Line ${index + 1}: cannot verify amount - ${missing} missing.`, evidence })
      return
    }

    const expected = roundTo(quantity * unitPrice, decimals)
    const statedRounded = roundTo(stated, decimals)
    if (expected !== statedRounded) {
      issues.push({
        path: `lines.${index}.value`,
        kind: 'line-amount',
        expected,
        stated: statedRounded,
        difference: roundTo(statedRounded - expected, decimals),
        message: `Line ${index + 1}: ${quantity} x ${unitPrice} = ${money(expected, decimals)}, but the stated amount is ${money(statedRounded, decimals)}.`,
        evidence,
      })
    }
  })

  const activeLines = shipment.lines.filter((line) => !isFreeOfCharge(line))
  const excluded = shipment.lines.length - activeLines.length
  const subtotal = roundTo(activeLines.reduce((total, line) => total + (line.value.value ?? 0), 0), decimals)
  const exclusionNote = excluded ? ` (${excluded} free-of-charge line${excluded > 1 ? 's' : ''} excluded)` : ''

  const declaredSubtotal = shipment.invoice.subtotal?.value ?? null
  if (declaredSubtotal != null) {
    const stated = roundTo(declaredSubtotal, decimals)
    if (stated !== subtotal) {
      issues.push({
        path: 'invoice.subtotal',
        kind: 'line-subtotal',
        expected: subtotal,
        stated,
        difference: roundTo(stated - subtotal, decimals),
        message: `Line items${exclusionNote} sum to ${money(subtotal, decimals)}, but the invoice subtotal states ${money(stated, decimals)}.`,
        evidence: sourceLabel(shipment.invoice.subtotal),
      })
    }
  }

  const declaredTotal = shipment.invoice.total?.value ?? null
  if (declaredTotal != null) {
    const freight = shipment.totals.freight.value ?? 0
    const insurance = shipment.totals.insurance.value ?? 0
    const stated = roundTo(declaredTotal, decimals)
    const candidates = [...new Set([
      subtotal,
      roundTo(subtotal + freight, decimals),
      roundTo(subtotal + insurance, decimals),
      roundTo(subtotal + freight + insurance, decimals),
    ])]
    if (!candidates.includes(stated)) {
      const expected = roundTo(subtotal + freight + insurance, decimals)
      const extras = freight || insurance ? ` plus freight ${money(freight, decimals)} and insurance ${money(insurance, decimals)}` : ''
      issues.push({
        path: 'invoice.total',
        kind: 'invoice-total',
        expected,
        stated,
        difference: roundTo(stated - expected, decimals),
        message: `Line items${exclusionNote}${extras} total ${money(expected, decimals)}, but the invoice total states ${money(stated, decimals)}.`,
        evidence: sourceLabel(shipment.invoice.total),
      })
    }
  }

  return issues
}

