import { describe, expect, it } from 'vitest'
import { currencyDecimals, isFreeOfCharge, roundTo, validateArithmetic } from '../src/lib/arithmetic'
import { shipmentSchema, type Shipment } from '../src/lib/shipment'

const field = <T>(value: T, confidence = 1) => ({ value, confidence })

type LineInput = {
  quantity?: number | null
  unitPrice?: number | null
  value?: number | null
  freeOfCharge?: boolean | null
}

function line(input: LineInput = {}) {
  return {
    description: field('Item'),
    countryOfOrigin: field('Vietnam'),
    htsCode: field('610910'),
    quantity: field(input.quantity === undefined ? 1 : input.quantity),
    unit: field('PCS'),
    value: field(input.value === undefined ? null : input.value),
    ...(input.unitPrice === undefined ? {} : { unitPrice: field(input.unitPrice) }),
    ...(input.freeOfCharge === undefined ? {} : { freeOfCharge: field(input.freeOfCharge) }),
  }
}

function shipment(overrides: { currency?: string; subtotal?: number | null; total?: number | null; freight?: number; insurance?: number; lines?: ReturnType<typeof line>[] } = {}): Shipment {
  return shipmentSchema.parse({
    importer: { name: field('Importer'), address: field('Portland'), taxId: field('12-3456789') },
    consignee: { name: field('Consignee'), address: field('Kent') },
    seller: { name: field('Seller'), address: field('Hong Kong') },
    invoice: {
      number: field('INV-1'), date: field('2026-09-12'), currency: field(overrides.currency ?? 'USD'), incoterm: field('CIF'),
      ...(overrides.subtotal === undefined ? {} : { subtotal: field(overrides.subtotal) }),
      ...(overrides.total === undefined ? {} : { total: field(overrides.total) }),
    },
    transport: { processingPort: field('3001'), entryPort: field('Tacoma'), loadingPort: field('Cat Lai, HCMC, VN'), dischargePort: field('Tacoma'), vessel: field('VESSEL'), voyage: field('041E'), billOfLading: field('BOL1'), arrivalDate: field('2026-10-14'), containers: [] },
    entry: { type: field('01'), bondType: field('09'), date: field('2026-10-14') },
    totals: { packages: field(1), grossWeight: field(1), freight: field(overrides.freight ?? 0), insurance: field(overrides.insurance ?? 0), assists: field(0) },
    lines: overrides.lines ?? [line({ quantity: 10, unitPrice: 5, value: 50 })],
    conflicts: [],
  })
}

describe('invoice arithmetic', () => {
  it('reports no issue when quantity x unit price equals the stated amount', () => {
    expect(validateArithmetic(shipment({ lines: [line({ quantity: 2400, unitPrice: 2.7, value: 6480 })] }))).toEqual([])
  })

  it('flags a line amount mismatch with expected, stated, and difference', () => {
    const [issue] = validateArithmetic(shipment({ lines: [line({ quantity: 10, unitPrice: 5, value: 55 })] }))
    expect(issue.kind).toBe('line-amount')
    expect(issue.expected).toBe(50)
    expect(issue.stated).toBe(55)
    expect(issue.difference).toBe(5)
  })

  it('tolerates floating point and rounding to currency precision', () => {
    expect(validateArithmetic(shipment({ lines: [line({ quantity: 3, unitPrice: 0.1, value: 0.3 })] }))).toEqual([])
    expect(validateArithmetic(shipment({ lines: [line({ quantity: 3, unitPrice: 1.333, value: 4 })] }))).toEqual([])
  })

  it('uses the currency minor unit (JPY has no decimals)', () => {
    expect(currencyDecimals('JPY')).toBe(0)
    expect(currencyDecimals('USD')).toBe(2)
    expect(validateArithmetic(shipment({ currency: 'JPY', lines: [line({ quantity: 1, unitPrice: 1000.6, value: 1000 })] }))).toHaveLength(1)
  })

  it('flags missing arithmetic inputs but skips lines with nothing to check', () => {
    const issues = validateArithmetic(shipment({ lines: [line({ quantity: null, unitPrice: 5, value: 50 }), line({ quantity: 1, value: 5 }), line({ quantity: null, value: null })] }))
    expect(issues.filter((issue) => issue.kind === 'missing-input')).toHaveLength(2)
    expect(issues.every((issue) => issue.path.startsWith('lines.'))).toBe(true)
  })

  it('excludes free-of-charge lines from the subtotal', () => {
    const value = shipment({
      subtotal: 50,
      lines: [line({ quantity: 10, unitPrice: 5, value: 50 }), line({ quantity: 1, unitPrice: 0, value: 0 }), line({ quantity: 2, unitPrice: 9, value: 18, freeOfCharge: true })],
    })
    expect(validateArithmetic(value)).toEqual([])
    expect(isFreeOfCharge(value.lines[1])).toBe(true)
    expect(isFreeOfCharge(value.lines[2])).toBe(true)
    expect(isFreeOfCharge(value.lines[0])).toBe(false)
  })

  it('flags a subtotal that does not match the line items', () => {
    const [issue] = validateArithmetic(shipment({ subtotal: 60, lines: [line({ quantity: 10, unitPrice: 5, value: 50 })] }))
    expect(issue.kind).toBe('line-subtotal')
    expect(issue.expected).toBe(50)
    expect(issue.stated).toBe(60)
  })

  it('accepts an invoice total that includes freight and insurance', () => {
    const value = shipment({ subtotal: 50, total: 4035, freight: 3850, insurance: 185, lines: [line({ quantity: 10, unitPrice: 5, value: 50 })] })
    expect(validateArithmetic(value)).toEqual([])
  })

  it('flags an invoice total that matches no valid composition', () => {
    const [issue] = validateArithmetic(shipment({ total: 9999, freight: 3850, insurance: 185, lines: [line({ quantity: 10, unitPrice: 5, value: 50 })] }))
    expect(issue.kind).toBe('invoice-total')
    expect(issue.expected).toBe(4085)
    expect(issue.stated).toBe(9999)
  })

  it('never mutates the shipment while checking', () => {
    const value = shipment({ lines: [line({ quantity: 10, unitPrice: 5, value: 55 })] })
    const before = JSON.stringify(value)
    validateArithmetic(value)
    expect(JSON.stringify(value)).toBe(before)
  })

  it('rounds to the requested precision', () => {
    expect(roundTo(1.005, 2)).toBe(1.01)
    expect(roundTo(2.675, 2)).toBe(2.68)
    expect(roundTo(1000.5, 0)).toBe(1001)
  })
})

