import { z } from 'zod'

const f = (schema: z.ZodType) => z.object({ value: schema.nullable(), confidence: z.number() })
const line = z.object({
  a: f(z.string()),
  opt: f(z.number()).optional(),
  def: f(z.number()).default({ value: null, confidence: 0 }),
})
const schema = z.toJSONSchema(z.object({ lines: z.array(line) })) as any
console.log('properties:', Object.keys(schema.properties.lines.items.properties))
console.log('required:', schema.properties.lines.items.required)
console.log('opt in schema?', 'opt' in schema.properties.lines.items.properties)
console.log('def in schema?', 'def' in schema.properties.lines.items.properties)
console.log('def json:', JSON.stringify(schema.properties.lines.items.properties.def))

