import { describe, expect, it } from 'vitest'
import { z } from 'zod'
import { shipmentSchema } from '../src/lib/shipment'

const field = <T>(value: T, confidence = 1) => ({ value, confidence })

// A model response that omits the arithmetic fields entirely.
const minimalShipment = {
  importer: { name: field('Importer'), address: field('Portland'), taxId: field('12-3456789') },
  consignee: { name: field('Consignee'), address: field('Kent') },
  seller: { name: field('Seller'), address: field('Hong Kong') },
  invoice: { number: field('INV-1'), date: field('2026-09-12'), currency: field('USD'), incoterm: field('CIF') },
  transport: { processingPort: field('3001'), entryPort: field('Tacoma'), loadingPort: field('Cat Lai, HCMC, VN'), dischargePort: field('Tacoma'), vessel: field('VESSEL'), voyage: field('041E'), billOfLading: field('BOL1'), arrivalDate: field('2026-10-14'), containers: [] },
  entry: { type: field('01'), bondType: field('09'), date: field('2026-10-14') },
  totals: { packages: field(1), grossWeight: field(1), freight: field(0), insurance: field(0), assists: field(0) },
  lines: [{ description: field('Item'), countryOfOrigin: field('Vietnam'), htsCode: field('610910'), quantity: field(10), unit: field('PCS'), value: field(50) }],
  conflicts: [],
}

describe('extraction model schema', () => {
  it('marks the arithmetic fields required so the model always emits them', () => {
    const schema = z.toJSONSchema(shipmentSchema) as any
    expect(schema.properties.lines.items.required).toEqual(expect.arrayContaining(['unitPrice', 'freeOfCharge']))
    expect(schema.properties.invoice.required).toEqual(expect.arrayContaining(['subtotal', 'total']))
  })

  it('fills the arithmetic fields with null defaults when the model omits them', () => {
    const shipment = shipmentSchema.parse(minimalShipment)
    expect(shipment.lines[0].unitPrice).toEqual({ value: null, confidence: 0 })
    expect(shipment.lines[0].freeOfCharge).toEqual({ value: null, confidence: 0 })
    expect(shipment.invoice.subtotal).toEqual({ value: null, confidence: 0 })
    expect(shipment.invoice.total).toEqual({ value: null, confidence: 0 })
  })

  it('keeps extracted arithmetic values through parsing', () => {
    const shipment = shipmentSchema.parse({
      ...minimalShipment,
      invoice: { ...minimalShipment.invoice, subtotal: field(50), total: field(50) },
      lines: [{ ...minimalShipment.lines[0], unitPrice: field(5), freeOfCharge: field(false) }],
    })
    expect(shipment.lines[0].unitPrice).toEqual({ value: 5, confidence: 1 })
    expect(shipment.invoice.subtotal).toEqual({ value: 50, confidence: 1 })
    expect(shipment.invoice.total).toEqual({ value: 50, confidence: 1 })
  })
})
